CREATE TABLE IF NOT EXISTS users (email_verified_at DATETIME NULL,id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,mobile VARCHAR(20) NOT NULL DEFAULT '',password VARCHAR(255) NOT NULL,active TINYINT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admin_users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('owner','manager') NOT NULL DEFAULT 'manager',active TINYINT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(120) UNIQUE NOT NULL,description TEXT,image VARCHAR(255) NOT NULL DEFAULT '',sort_order INT NOT NULL DEFAULT 0,active TINYINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,slug VARCHAR(180) UNIQUE NOT NULL,description TEXT,short_description VARCHAR(255) NOT NULL DEFAULT '',ingredients TEXT,allergens TEXT,storage TEXT,shelf_life VARCHAR(100) NOT NULL DEFAULT '',image VARCHAR(255) NOT NULL DEFAULT 'assets/images/hero.png',featured TINYINT NOT NULL DEFAULT 0,active TINYINT NOT NULL DEFAULT 1,seo_title VARCHAR(180) NOT NULL DEFAULT '',seo_description VARCHAR(255) NOT NULL DEFAULT '',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE IF NOT EXISTS product_images (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,path VARCHAR(255) NOT NULL,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS product_variants (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,sku VARCHAR(100) NOT NULL UNIQUE,label VARCHAR(60) NOT NULL,price INT UNSIGNED NOT NULL,compare_price INT UNSIGNED NOT NULL DEFAULT 0,stock INT UNSIGNED NOT NULL DEFAULT 0,active TINYINT NOT NULL DEFAULT 1,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS inventory_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,variant_id BIGINT UNSIGNED NOT NULL,quantity INT NOT NULL,reason VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(variant_id) REFERENCES product_variants(id));
CREATE TABLE IF NOT EXISTS carts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,coupon VARCHAR(60) NOT NULL DEFAULT '',updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS bundles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,description TEXT,min_items INT UNSIGNED NOT NULL DEFAULT 3,discount_percent INT UNSIGNED NOT NULL DEFAULT 10,fixed_price INT UNSIGNED NOT NULL DEFAULT 0,starts_at DATETIME NULL,ends_at DATETIME NULL,active TINYINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS bundle_items (bundle_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(bundle_id,product_id),FOREIGN KEY(bundle_id) REFERENCES bundles(id),FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS cart_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,cart_id BIGINT UNSIGNED NOT NULL,variant_id BIGINT UNSIGNED NOT NULL,quantity INT UNSIGNED NOT NULL,bundle_id BIGINT UNSIGNED NULL,bundle_group VARCHAR(40) NOT NULL DEFAULT '',FOREIGN KEY(cart_id) REFERENCES carts(id),FOREIGN KEY(variant_id) REFERENCES product_variants(id),FOREIGN KEY(bundle_id) REFERENCES bundles(id));
CREATE TABLE IF NOT EXISTS addresses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,mobile VARCHAR(20) NOT NULL,address TEXT NOT NULL,city VARCHAR(100) NOT NULL,state VARCHAR(100) NOT NULL,pincode VARCHAR(6) NOT NULL,instructions TEXT,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS coupons (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(60) NOT NULL UNIQUE,type ENUM('percent','fixed') NOT NULL DEFAULT 'percent',value INT UNSIGNED NOT NULL,min_total INT UNSIGNED NOT NULL DEFAULT 0,max_discount INT UNSIGNED NOT NULL DEFAULT 0,usage_limit INT UNSIGNED NOT NULL DEFAULT 100,per_customer_limit INT UNSIGNED NOT NULL DEFAULT 1,product_id BIGINT UNSIGNED NULL,category_id BIGINT UNSIGNED NULL,starts_at DATETIME NULL,ends_at DATETIME NULL,active TINYINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS orders (courier VARCHAR(100) NOT NULL DEFAULT '',tracking_url VARCHAR(500) NOT NULL DEFAULT '',expected_delivery DATE NULL,id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,number VARCHAR(40) NOT NULL UNIQUE,idempotency_key VARCHAR(64) NOT NULL UNIQUE,address_json TEXT NOT NULL,subtotal INT UNSIGNED NOT NULL,discount INT UNSIGNED NOT NULL,shipping INT UNSIGNED NOT NULL,tax INT UNSIGNED NOT NULL,total INT UNSIGNED NOT NULL,coupon VARCHAR(60) NOT NULL DEFAULT '',payment_method ENUM('cod','razorpay') NOT NULL,payment_status ENUM('pending','paid','failed','refunded') NOT NULL DEFAULT 'pending',status ENUM('Pending','Confirmed','Processing','Packed','Shipped','Out for delivery','Delivered','Cancelled') NOT NULL DEFAULT 'Pending',razorpay_order_id VARCHAR(100) NULL UNIQUE,tracking VARCHAR(200) NOT NULL DEFAULT '',notes TEXT,stock_restored TINYINT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),INDEX(created_at),INDEX(status));
CREATE TABLE IF NOT EXISTS order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,variant_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,variant VARCHAR(60) NOT NULL,price INT UNSIGNED NOT NULL,quantity INT UNSIGNED NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(variant_id) REFERENCES product_variants(id));
CREATE TABLE IF NOT EXISTS payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,provider_id VARCHAR(100) NOT NULL UNIQUE,amount INT UNSIGNED NOT NULL,status VARCHAR(30) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE IF NOT EXISTS payment_webhook_events (id VARCHAR(100) PRIMARY KEY,event VARCHAR(100) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS coupon_usage (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,coupon_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NOT NULL UNIQUE,FOREIGN KEY(coupon_id) REFERENCES coupons(id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE IF NOT EXISTS reviews (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,rating TINYINT UNSIGNED NOT NULL,body TEXT NOT NULL,image VARCHAR(255) NOT NULL DEFAULT '',status ENUM('pending','approved','hidden') NOT NULL DEFAULT 'pending',response TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,product_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS store_settings (setting_key VARCHAR(100) PRIMARY KEY,setting_value MEDIUMTEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_id BIGINT UNSIGNED NULL,action VARCHAR(120) NOT NULL,details VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS password_resets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash VARCHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS rate_limits (bucket VARCHAR(64) PRIMARY KEY,attempts INT NOT NULL,expires_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS newsletter_subscribers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS contact_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS email_otps (
 kind ENUM('customer','admin') NOT NULL,
 account_id BIGINT UNSIGNED NOT NULL,
 challenge_id CHAR(64) NOT NULL UNIQUE,
 email VARCHAR(190) NOT NULL,
 code_hash CHAR(64) NOT NULL,
 credential_hash CHAR(64) NOT NULL,
 expires_at DATETIME NOT NULL,
 attempts TINYINT UNSIGNED NOT NULL DEFAULT 0,
 consumed_at DATETIME NULL,
 sent_at DATETIME NOT NULL,
 window_start DATETIME NOT NULL,
 send_count INT UNSIGNED NOT NULL DEFAULT 1,
 PRIMARY KEY(kind,account_id)
);

CREATE TABLE IF NOT EXISTS order_events (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 order_id BIGINT UNSIGNED NOT NULL,
 event_key VARCHAR(120) NOT NULL,
 title VARCHAR(120) NOT NULL,
 detail TEXT NOT NULL,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 UNIQUE(order_id,event_key),FOREIGN KEY(order_id) REFERENCES orders(id)
);
CREATE TABLE IF NOT EXISTS invoices (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 order_id BIGINT UNSIGNED NOT NULL UNIQUE,
 number VARCHAR(60) NOT NULL UNIQUE,
 snapshot MEDIUMTEXT NOT NULL,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(order_id) REFERENCES orders(id)
);
CREATE TABLE IF NOT EXISTS order_emails (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 order_id BIGINT UNSIGNED NOT NULL,
 event_key VARCHAR(120) NOT NULL,
 recipient VARCHAR(190) NOT NULL,
 subject VARCHAR(255) NOT NULL,
 body TEXT NOT NULL,
 invoice_id BIGINT UNSIGNED NULL,
 state ENUM('pending','sending','sent','failed') NOT NULL DEFAULT 'pending',
 attempts INT UNSIGNED NOT NULL DEFAULT 0,
 last_error VARCHAR(255) NOT NULL DEFAULT '',
 sent_at DATETIME NULL,
 attempted_at DATETIME NULL,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 UNIQUE(order_id,event_key),FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(invoice_id) REFERENCES invoices(id)
);
